class BankAccount {
    owner: string
    balance: number

    constructor(owner: string, initial: number = 0) {
        this.owner = owner
        this.balance = initial
    }

    deposit(amount: number): void {
        this.balance += amount
    }

    withdraw(amount: number): boolean {
        if (amount > this.balance) return false
        this.balance -= amount
        return true
    }

    summary(): string {
        return `${this.owner}: ${this.balance} so'm`
    }
}

const acc = new BankAccount("Rustam", 100_000)
acc.deposit(50_000)
console.log(acc.withdraw(500_000))   // mablag' yetmaydi
console.log(acc.withdraw(30_000))
