class Statistics {
    private values: number[] = []

    add(...numbers: number[]): this {
        this.values.push(...numbers)
        return this
    }

    get count(): number { return this.values.length }
    get sum(): number { return this.values.reduce((a, b) => a + b, 0) }
    get average(): number { return this.count === 0 ? 0 : this.sum / this.count }
    get min(): number { return Math.min(...this.values) }
    get max(): number { return Math.max(...this.values) }
}

const stats = new Statistics()
stats.add(10, 20).add(30).add(40, 50)

console.log(`Soni: ${stats.count}, yig'indi: ${stats.sum}`)
console.log(`O'rtacha: ${stats.average}, min: ${stats.min}, max: ${stats.max}`)

