class TrafficLight {
    private static readonly sequence = ["qizil", "sariq", "yashil"] as const
    private index = 0

    get current(): string {
        return TrafficLight.sequence[this.index]
    }

    next(): string {
        this.index = (this.index + 1) % TrafficLight.sequence.length
        return this.current
    }

    get canGo(): boolean {
        return this.current === "yashil"
    }
}

