class PasswordChecker {
    check(pw: string) {
        const score = this.lengthScore(pw) + this.varietyScore(pw)
        return score >= 4 ? "kuchli" : score >= 2 ? "o'rtacha" : "zaif"
    }
    private lengthScore(pw: string) { return pw.length >= 12 ? 2 : pw.length >= 8 ? 1 : 0 }
    private varietyScore(pw: string) { return [/[a-z]/, /[A-Z]/, /\d/, /\W/].filter(r => r.test(pw)).length - 1 }
}
const pc = new PasswordChecker()
console.log(["abc", "Salom123", "Kuchli!Parol2024"].map(p => pc.check(p)))

