interface Repository<T> { add(x: T): void; all(): T[]; remove(pred: (x: T) => boolean): number }
class ArrayRepo<T> implements Repository<T> {
    private items: T[] = []
    add(x: T) { this.items.push(x) }
    all() { return [...this.items] }
    remove(pred: (x: T) => boolean) { const before = this.items.length; this.items = this.items.filter(x => !pred(x)); return before - this.items.length }
}
