function memoized<T extends (...args: any[]) => any>(target: T, context: ClassMethodDecoratorContext) {
    const cache = new Map<string, any>()
    return function (this: any, ...args: any[]) {
        const key = JSON.stringify(args)
        if (cache.has(key)) {
            console.log(`(keshdan) ${String(context.name)}(${args})`)
            return cache.get(key)
        }
        const result = target.apply(this, args)
        cache.set(key, result)
        console.log(`(hisoblandi) ${String(context.name)}(${args})`)
        return result
    } as T
}

