function retry(attempts: number) {
    return function <T extends (...args: any[]) => any>(target: T, context: ClassMethodDecoratorContext) {
        return function (this: any, ...args: any[]) {
            let lastError: unknown
            for (let i = 1; i <= attempts; i++) {
