type Check = (value: unknown) => boolean
const isString: Check = value => typeof value === "string"
const isPositive: Check = value => typeof value === "number" && value > 0

function validate(...checks: Check[]) {
    return function (target: (...args: any[]) => any, context: { name: string | symbol }) {
        return function (this: unknown, ...args: any[]) {
            checks.forEach((check, i) => {
                if (!check(args[i])) throw new TypeError(`${String(context.name)}: ${i + 1}-argument noto'g'ri`)
            })
            return target.apply(this, args)
        }
    }
}

