function memo<T extends (...args: any[]) => any>(target: T, _context: { name: string | symbol }): T {
    const cache = new Map<string, unknown>()
    return function (this: unknown, ...args: any[]) {
        const key = JSON.stringify(args)
        if (!cache.has(key)) cache.set(key, target.apply(this, args))
        return cache.get(key)
    } as T
}

