type DecoratorFn = (value: (...args: any[]) => any, context: { name: string | symbol }) => ((...args: any[]) => any) | void

function applyMethodDecorator(proto: any, name: string, decorator: DecoratorFn): void {
    const replacement = decorator(proto[name], { name })
    if (replacement) proto[name] = replacement          // undefined bo'lsa — o'zgarmaydi
}

const observe: DecoratorFn = (_value, context) => {
    console.log(`kuzatildi: ${String(context.name)}`)    // hech narsa qaytarmaydi
}

const shout: DecoratorFn = value => (...args: any[]) => String(value(...args)).toUpperCase()

class Greeter {
    hello() { return "salom" }
    bye() { return "xayr" }
}

applyMethodDecorator(Greeter.prototype, "hello", observe)
applyMethodDecorator(Greeter.prototype, "bye", shout)

const greeter = new Greeter()
console.log(greeter.hello(), greeter.bye())

function withCache<A extends unknown[], R>(fn: (...args: A) => R) {
    const cache = new Map<string, R>()
    return (...args: A): R => {
        const key = JSON.stringify(args)
        if (!cache.has(key)) cache.set(key, fn(...args))
        return cache.get(key)!
    }
}

let runs = 0
const slowDouble = (n: number) => { runs++; return n * 2 }
const fastDouble = withCache(slowDouble)

